async def main() -> None:
    apply = "--apply" in sys.argv

    async with async_session() as db:
        unis = (await db.execute(select(University).where(University.slug.in_(UPDATES.keys())))).scalars().all()
        by_slug = {u.slug: u for u in unis}

        changed = 0
        for slug, (old_desc, new_desc) in UPDATES.items():
            uni = by_slug.get(slug)
            if uni is None:
                print(f"  ! university not found: {slug}")
                continue
            if uni.description != old_desc:
                print(f"  - skip (description already changed): {slug} current={uni.description!r}")
                continue
            tag = "[updating]" if apply else "[would update]"
            print(f"{tag} {slug}")
            if apply:
                uni.description = new_desc
            changed += 1

        print(f"\n{changed} of {len(UPDATES)} universities would be updated.")
        if apply:
            await db.commit()
            print("Committed.")
        else:
            print("Dry run — nothing written. Re-run with --apply to commit.")


if __name__ == "__main__":
    asyncio.run(main())
